levels[0] = newLevel;
levels[1] = newLevel;
levels[2] = newLevel;
global.set('uvLevel', msg.payload);
const modbusMsg = {payload:
                    {   value: levels,
                        uintid: '1',
                        fc: '16',
                        address: '0',
                        quantity: '3' }
}
return modbusMsg;

msg.topic = "Restart Comfirmation";
msg.payload = "Are you sure you want to reboot?";
return msg;

if (msg.payload === 'OK') {
    const msgLEDSoff = {payload: true};
    return [msg, msgLEDSoff];
}

msg.topic = "Shutdown Comfirmation";
msg.payload = "Are you sure you want to shutdown? To restart after shutdown power must be disconnected and re-connected";
return msg;

if (msg.payload === 'OK') {
    const msgLEDSoff = {payload: true};
    return [msg, msgLEDSoff];
}

let runBtnState = !global.get('runState');
let autoEnabled = global.get('autoEnabled');
if (!autoEnabled) runBtnState = false;
let colour = '#888888'

if (runBtnState) colour = '#00aa00';

msg = {enabled:runBtnState, background:colour};
return msg;

let stopBtnState = global.get('runState');
let autoEnabled = global.get('autoEnabled');
if (!autoEnabled) stopBtnState = false;
let colour = '#888888'

if (stopBtnState) colour = '#aa0000';

msg = {enabled:stopBtnState, background:colour};
return msg;

if (msg.payload == false) {
    global.set('autoEnabled', false);
    global.set('runState', false);
}
else global.set('autoEnabled', true);
msg.payload = 0;
return msg;

if (msg.payload == true) {
    global.set('runState', true);
}
return msg;

if (msg.payload == true) {
    global.set('runState', false);
    msg.payload = 0;
}
return msg;

const running = global.get('runState');

if (running) {
    // Get current timestamp, offset for timezone and zero adjust
    const dateTime = new Date();
    const tzOffset = -(dateTime.getTimezoneOffset() * 60 * 1000);
    //node.warn("tzOffset = " + tzOffset);
    const unixtime = dateTime.getTime() + tzOffset;
    //node.warn("unixtime = " + unixtime);
    const millisInOneDay = 24 * 60 * 60 * 1000;
    const millisToday = unixtime % millisInOneDay;
    //node.warn("millisToday = " + millisToday);

    // Get current time range from program array
    const progArray = global.get('run_prog_array');
    let ptr = 0;
    for (let i = 19; i >= 0; i--) {
        if (progArray[i][0] < millisToday) {
            ptr = i;
            break;
        }
    }

    let ptr2 = ptr + 1;
    //node.warn("ptr = " + ptr);

    if (ptr2 > 19) ptr2 = 0;
    const tmRangeStart = progArray[ptr][0];
    //node.warn("tmRangeStart = " + tmRangeStart);
    const tmRangeEnd = progArray[ptr2][0];
    //node.warn("tmRangeEnd = " + tmRangeEnd);
    const tmRangePositionFactor = (millisToday - tmRangeStart) / (tmRangeEnd - tmRangeStart);
    //node.warn("tmRangePositionFactor = " + tmRangePositionFactor);
    const uvRangeStart = progArray[ptr][1];
    //node.warn("uvRangeStart = " + uvRangeStart);
    const uvRangeEnd = progArray[ptr2][1];
    //node.warn("uvRangeEnd = " + uvRangeEnd);
    const uvLevelNow = uvRangeStart + ((uvRangeEnd - uvRangeStart) * tmRangePositionFactor);
    //node.warn("uvLevelNow = " + uvLevelNow);

    const uvLevel = global.get('uvLevel');
    const uvLevelNowRounded = uvLevelNow.toFixed(1);
    if (uvLevel != uvLevelNowRounded) {
        msg.payload = uvLevelNowRounded;
        return msg;
    }
}

return;

