let autoMode = global.get('autoEnabled');
let running = global.get('runState');
let uvLevel = global.get('uvLevel');
if (autoMode && running) msg = {payload:"Running", fcolor:"#22ff22"};
else if (autoMode && !running) msg = { payload: "Stopped", fcolor: "aa0000" };
else if (uvLevel > 0) msg = { payload: "UV on", fcolor: "5500ff" };
else msg.payload = msg = { payload: "UV off", fcolor: "aaaaaa" };
return msg;

if (msg.payload === 'startup' || msg.payload === 'connect') {
    flow.set('startup', true);
    node.status({fill:"green",shape:"ring",text:msg.payload});
}
if (msg.payload === 'change') {
    if (flow.get('startup')){
        if (msg.tab == 0) {
            msg.payload = "+1"
            return msg;
        }
        flow.set('startup', false);
    }
    node.status({fill:"blue",shape:"ring",text:"Tab: " + msg.name});
}
return;

if (msg.payload === '+1') {
