return;

if (msg.payload === "") {
    msg.payload = "-1"
    return msg;
}
return;

const temps = msg.payload.slice(0,3);
const fanSpeed = msg.payload[3] * 0.1;
let tempC = (Math.max(...temps) * 0.1);

const msg1 = {payload: tempC.toFixed(1)};
const msg2 = {payload: fanSpeed.toFixed(1)};

// Check for overheating
if (tempC > 70) {
    const overheatText = ("Overheat! Sensor reading " + tempC + " °C!!! Shutting down...");
    const msgOverheat = {payload:overheatText};
    const msgLEDoff = {payload: true};
    return [msg1, msg2, msgOverheat, msgLEDoff];
}

return [msg1, msg2];

